// Cache-first for everything: once installed the page never needs the network.
const CACHE = "japan-day-board-2026-11-22-1749-be027c05";
const FILES = ["./", "index.html", "manifest.webmanifest", "icon-180.png", "icon-512.png", "check-pins.html"];

self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", e => {
  e.waitUntil(
    caches.keys()
      .then(ks => Promise.all(ks.filter(k => k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

// Network first, but only for as long as a network is plausibly there.
// Cache-first was serving a stale build even after a redeploy; waiting forever on
// a dead radio would be just as bad in Japan, so the fetch races a short timer and
// the cache wins the moment the network does not answer.
const NET_TIMEOUT = 2500;

function fromNetwork(req){
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("slow")), NET_TIMEOUT);
    fetch(req).then(res => { clearTimeout(timer); resolve(res); },
                    err => { clearTimeout(timer); reject(err); });
  });
}

self.addEventListener("fetch", e => {
  const url = new URL(e.request.url);
  if(url.origin !== self.location.origin) return;   // leave Google/TikTok alone
  if(e.request.method !== "GET") return;

  e.respondWith(
    fromNetwork(e.request)
      .then(res => {
        if(res && res.ok){
          const copy = res.clone();
          caches.open(CACHE).then(c => c.put(e.request, copy));
        }
        return res;
      })
      .catch(() =>
        caches.match(e.request, {ignoreSearch:true})
          .then(hit => hit || caches.match("./index.html", {ignoreSearch:true}))
      )
  );
});
